('bmlt-advanced-haematology-smear-reticulocyte-marrow-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',3300,$json${"question":"What is the preferred anticoagulant for a routine peripheral blood smear?","translation":"","options":["EDTA","Sodium citrate","Heparin","Sodium fluoride"],"correctIndex":0,"explanation":"EDTA preserves cellular morphology for routine blood film preparation.","explanationNe":"EDTA ले routine blood film का रक्तकोषहरूको आकार राम्रोसँग सुरक्षित राख्छ।","topic":"Peripheral blood smear"}$json$::jsonb,true),
('bmlt-advanced-haematology-smear-reticulocyte-marrow-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',3301,$json${"question":"Which area of a well-made wedge smear is best for examining individual red cells?","translation":"","options":["Thick body of the smear","Feathered edge only","Monolayer just behind the feathered edge","Unspread drop near the slide label"],"correctIndex":2,"explanation":"The monolayer has red cells distributed singly with minimal overlap.","explanationNe":"Feathered edge भन्दा अलि पछाडिको monolayer क्षेत्रमा RBC हरू कम overlap हुन्छन्।","topic":"Peripheral blood smear"}$json$::jsonb,true),
