('bmlt-advanced-haematology-smear-reticulocyte-marrow-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',3310,$json${"question":"The supravital stain commonly used for reticulocyte counting is:","translation":"","options":["New methylene blue","Leishman stain","Safranin","Carbol fuchsin"],"correctIndex":0,"explanation":"New methylene blue precipitates residual reticulocyte RNA, making it visible.","explanationNe":"New methylene blue ले reticulocyte को residual RNA देखिने बनाउँछ।","topic":"Reticulocyte count"}$json$::jsonb,true),
('bmlt-advanced-haematology-smear-reticulocyte-marrow-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',3311,$json${"question":"A reticulocyte count is most useful for assessing:","translation":"","options":["Bone marrow response to anaemia","Platelet function","Coagulation factor activity","Serum iron binding capacity"],"correctIndex":0,"explanation":"Reticulocytes indicate marrow red-cell production response.","explanationNe":"Reticulocyte count ले anaemia प्रति bone marrow को प्रतिक्रिया देखाउँछ।","topic":"Reticulocyte count"}$json$::jsonb,true),
