('bmlt-advanced-haematology-smear-reticulocyte-marrow-mock-005','BMLT','BMLT NHPC Licensing','mock','free',3404,$json${"question":"A reticulocyte percentage is 6% in a patient with severe anaemia. Why may the corrected reticulocyte count be needed?","translation":"","options":["To account for the reduced red-cell count/haematocrit","To measure platelet size","To correct serum bilirubin","To identify blood group"],"correctIndex":0,"explanation":"The percentage can overstate marrow response in anaemia; correction accounts for the reduced red-cell mass.","explanationNe":"Anaemia मा RBC mass कम हुने भएकाले percentage मात्रले marrow response बढी देखाउन सक्छ।","topic":"Reticulocyte calculation"}$json$::jsonb,true),
